import type { Amount, CardDef, Effect, EffectTarget, InfraId, StatusId } from "../engine/types";
import { byId } from "./byId";

/*
 * Every card in the game. Rules text is generated by the engine from `effects`,
 * so only names and flavour are written here.
 * Balance guide: 1 Engineer is worth about 6 Serve or 5 Capacity.
 */

// ---------- effect helpers ----------

const serve = (amount: Amount, times?: number, target: EffectTarget = "enemy"): Effect =>
  times && times > 1 ? { op: "serve", amount, times, target } : { op: "serve", amount, target };
const serveAll = (amount: Amount, times?: number): Effect => serve(amount, times, "allEnemies");
const serveRandom = (amount: Amount, times?: number): Effect => serve(amount, times, "randomEnemy");
const capacity = (amount: Amount): Effect => ({ op: "capacity", amount });
const reject = (amount: Amount): Effect => ({ op: "reject", amount });
const draw = (amount: number): Effect => ({ op: "draw", amount });
const engineers = (amount: number): Effect => ({ op: "engineers", amount });
const recover = (amount: Amount): Effect => ({ op: "recover", amount });
const loseBudget = (amount: number): Effect => ({ op: "loseBudget", amount });
const self = (status: StatusId, amount: number): Effect => ({ op: "status", status, amount, target: "self" });
const onEnemy = (status: StatusId, amount: number, target: EffectTarget = "enemy"): Effect => ({ op: "status", status, amount, target });
const infra = (id: InfraId, stacks = 1): Effect => ({ op: "infra", infra: id, stacks });
const warm = (amount: number): Effect => ({ op: "warmCache", amount });
const onRead = (...then: Effect[]): Effect => ({ op: "if", cond: { kind: "workload", is: "read" }, then });
const onWrite = (...then: Effect[]): Effect => ({ op: "if", cond: { kind: "workload", is: "write" }, then });
const below = (pct: number, ...then: Effect[]): Effect => ({ op: "if", cond: { kind: "budgetBelowPct", pct }, then });

/** Cards that point at one enemy need a target; everything else is played on the board. */
function targetsEnemy(effects: Effect[]): boolean {
  return effects.some((e) => {
    if (e.op === "if") return targetsEnemy(e.then);
    return (e.op === "serve" || e.op === "status") && e.target === "enemy";
  });
}

type Def = Omit<CardDef, "target">;

function card(def: Def): CardDef {
  const full: CardDef = { ...def, target: targetsEnemy(def.effects) ? "enemy" : "none" };
  if (def.upgrade?.effects) {
    const upTarget = targetsEnemy(def.upgrade.effects) ? "enemy" : "none";
    if (upTarget !== full.target) full.upgrade = { ...def.upgrade, target: upTarget };
  }
  return full;
}

